// ============================================
// ESP32 CAR - MOTOR TORQUE TEST
// No controller / No ESP-NOW
// ============================================

// LEFT BTS7960
#define LEFT_R_EN   27
#define LEFT_L_EN   14
#define LEFT_RPWM   25
#define LEFT_LPWM   26

// RIGHT BTS7960
#define RIGHT_R_EN  33
#define RIGHT_L_EN  32
#define RIGHT_RPWM  18
#define RIGHT_LPWM  19

// PWM settings
#define PWM_FREQ 20000
#define PWM_RES  8

// 75% power
#define TEST_SPEED 192


// ============================================
// STOP
// ============================================

void stopMotors() {

  ledcWrite(LEFT_RPWM, 0);
  ledcWrite(LEFT_LPWM, 0);

  ledcWrite(RIGHT_RPWM, 0);
  ledcWrite(RIGHT_LPWM, 0);
}


// ============================================
// FORWARD
// ============================================

void forward() {

  ledcWrite(LEFT_RPWM, TEST_SPEED);
  ledcWrite(LEFT_LPWM, 0);

  ledcWrite(RIGHT_RPWM, TEST_SPEED);
  ledcWrite(RIGHT_LPWM, 0);

  Serial.println("FORWARD");
}


// ============================================
// REVERSE
// ============================================

void reverse() {

  ledcWrite(LEFT_RPWM, 0);
  ledcWrite(LEFT_LPWM, TEST_SPEED);

  ledcWrite(RIGHT_RPWM, 0);
  ledcWrite(RIGHT_LPWM, TEST_SPEED);

  Serial.println("REVERSE");
}


// ============================================
// TURN LEFT
// ============================================

void turnLeft() {

  // Left side reverse
  ledcWrite(LEFT_RPWM, 0);
  ledcWrite(LEFT_LPWM, TEST_SPEED);

  // Right side forward
  ledcWrite(RIGHT_RPWM, TEST_SPEED);
  ledcWrite(RIGHT_LPWM, 0);

  Serial.println("LEFT");
}


// ============================================
// TURN RIGHT
// ============================================

void turnRight() {

  // Left side forward
  ledcWrite(LEFT_RPWM, TEST_SPEED);
  ledcWrite(LEFT_LPWM, 0);

  // Right side reverse
  ledcWrite(RIGHT_RPWM, 0);
  ledcWrite(RIGHT_LPWM, TEST_SPEED);

  Serial.println("RIGHT");
}


// ============================================
// SETUP
// ============================================

void setup() {

  Serial.begin(115200);

  // Enable BTS7960 drivers
  pinMode(LEFT_R_EN, OUTPUT);
  pinMode(LEFT_L_EN, OUTPUT);

  pinMode(RIGHT_R_EN, OUTPUT);
  pinMode(RIGHT_L_EN, OUTPUT);

  digitalWrite(LEFT_R_EN, HIGH);
  digitalWrite(LEFT_L_EN, HIGH);

  digitalWrite(RIGHT_R_EN, HIGH);
  digitalWrite(RIGHT_L_EN, HIGH);


  // Attach PWM
  ledcAttach(LEFT_RPWM, PWM_FREQ, PWM_RES);
  ledcAttach(LEFT_LPWM, PWM_FREQ, PWM_RES);

  ledcAttach(RIGHT_RPWM, PWM_FREQ, PWM_RES);
  ledcAttach(RIGHT_LPWM, PWM_FREQ, PWM_RES);


  // Start stopped
  stopMotors();

  Serial.println();
  Serial.println("==============================");
  Serial.println("ESP32 MOTOR TORQUE TEST");
  Serial.println("==============================");
  Serial.println("Power: 75% (192/255)");
  Serial.println();
}


// ============================================
// MAIN LOOP
// ============================================

void loop() {

  // FORWARD
  forward();
  delay(3000);

  // STOP
  stopMotors();
  Serial.println("STOP");
  delay(1500);


  // REVERSE
  reverse();
  delay(3000);

  // STOP
  stopMotors();
  Serial.println("STOP");
  delay(1500);


  // LEFT
  turnLeft();
  delay(3000);

  // STOP
  stopMotors();
  Serial.println("STOP");
  delay(1500);


  // RIGHT
  turnRight();
  delay(3000);

  // STOP
  stopMotors();
  Serial.println("STOP");
  delay(1500);


  // Then repeat
}
